    //Driver Code Starts
#include <iostream>
#include <vector>
#include <climits>
using namespace std;


//Driver Code Ends

void dfs(int node, int currentTime, vector<vector<pair<int,int>>>& adj,
         vector<int>& vis, int V, int& shortest, int& ways) {

    // prune: no need to go further
    if (currentTime > shortest) return;

    if (node == V - 1) {

        // if time to reach the node is new minimum
        // change the number of ways to 1(for current path)
        if (currentTime < shortest) {
            shortest = currentTime;
            ways = 1;
        }

        // increment the number of ways to 
        // reach the node in shortest time
        else if (currentTime == shortest) {
            ways++;
        }
        return;
    }

    vis[node] = 1;

    for (auto &p : adj[node]) {
        int next = p.first;
        int wt = p.second;
        if (vis[next] == 0) {
            dfs(next, currentTime + wt, adj, vis, V, shortest, ways);
        }
    }

    // backtracking and marking 
    // node as unvisited
    vis[node] = 0;
}

int countPaths(vector<vector<pair<int,int>>>& adj) {
    int V = adj.size();
    vector<int> vis(V, 0);

    // to store the shortest time 
    // needed to reach node V-1 from 0
    int shortest = INT_MAX;

    // number of ways to reach
    // node V-1 in shortest time
    int ways = 0;
    dfs(0, 0, adj, vis, V, shortest, ways);
    return ways;
}

//Driver Code Starts

void addEdge(vector<vector<pair<int,int>>>& adj, int u, int v, int wt) {
    adj[u].push_back({v, wt});
    adj[v].push_back({u, wt});
}

int main() {
    int V = 4;
    vector<vector<pair<int,int>>> adj(V);

    addEdge(adj, 0, 1, 2);
    addEdge(adj, 0, 3, 5);
    addEdge(adj, 1, 2, 3);
    addEdge(adj, 1, 3, 3);
    addEdge(adj, 2, 3, 4);

    cout << countPaths(adj);
}

